namespace RaceDay.Api.Models;
public sealed class Role { public int RoleId { get; set; } public string RoleName { get; set; } = ""; public List<User> Users { get; set; } = []; }
public sealed class User { public int UserId { get; set; } public int RoleId { get; set; } public Role? Role { get; set; } public string FullName { get; set; } = ""; public string Email { get; set; } = ""; public string PasswordHash { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public List<Event> Events { get; set; } = []; public List<Enrolment> Enrolments { get; set; } = []; }
public sealed class Event { public int EventId { get; set; } public int OrganiserId { get; set; } public User? Organiser { get; set; } public string EventName { get; set; } = ""; public string? Description { get; set; } public DateTime EventDate { get; set; } public string Location { get; set; } = ""; public string? RouteInfo { get; set; } public decimal EventDistanceKm { get; set; } public string EventType { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public List<Category> Categories { get; set; } = []; }
public sealed class Category { public int CategoryId { get; set; } public int EventId { get; set; } public Event? Event { get; set; } public string CategoryName { get; set; } = ""; public decimal DistanceKm { get; set; } public int MaxParticipants { get; set; } = 100; public List<Enrolment> Enrolments { get; set; } = []; }
public sealed class Enrolment { public int EnrolmentId { get; set; } public int ParticipantId { get; set; } public User? Participant { get; set; } public int CategoryId { get; set; } public Category? Category { get; set; } public DateTime EnrolmentDate { get; set; } = DateTime.UtcNow; public string Status { get; set; } = "Registered"; public Result? Result { get; set; } }
public sealed class Result { public int ResultId { get; set; } public int EnrolmentId { get; set; } public Enrolment? Enrolment { get; set; } public TimeSpan FinishTime { get; set; } public int? Position { get; set; } public int RecordedByUserId { get; set; } public User? RecordedBy { get; set; } public DateTime RecordedAt { get; set; } = DateTime.UtcNow; }
